def play(n, alice_nums, bob_nums, turn, memo):
    state = (tuple(sorted(alice_nums)), tuple(sorted(bob_nums)), turn)
    if state in memo:
        return memo[state]

    all_chosen = set(alice_nums) | set(bob_nums)
    if len(all_chosen) == n:
        return 0

    current_nums = alice_nums if turn == 0 else bob_nums
    possible_moves = []
    for i in range(1, n + 1):
        if i not in all_chosen:
            if all(abs(i - num) != 1 for num in current_nums):
                possible_moves.append(i)

    if not possible_moves:
        return -1

    can_draw = False
    for move in possible_moves:
        if turn == 0:
            res = play(n, alice_nums + (move,), bob_nums, 1, memo)
        else:
            res = play(n, alice_nums, bob_nums + (move,), 0, memo)

        if res == -1:
            memo[state] = 1
            return 1
        if res == 0:
            can_draw = True

    if can_draw:
        memo[state] = 0
        return 0

    memo[state] = -1
    return -1

