            if state in memo: return memo[state]
            res = solve(mask_bob, mask_alice, 0)
            memo[(mask_alice, mask_bob, 1)] = res
            return res

        state = (mask_alice, mask_bob, turn)
        if state in memo:
            return memo[state]

