        # mask_alice | mask_bob is the set of taken numbers
        taken = mask_alice | mask_bob
        moves = []
        for i in range(n):
            if not (taken & (1 << i)):
                # Check if i is consecutive to any in mask_alice
                # A number i is consecutive to i-1 or i+1.
                # We need to check if i-1 or i+1 is in mask_alice.
                is_consecutive = False
                if i > 0 and (mask_alice & (1 << (i-1))):
                    is_consecutive = True
                if i < n-1 and (mask_alice & (1 << (i+1))):
                    is_consecutive = True

                if not is_consecutive:
                    moves.append(i)

        if not moves:
            if taken == (1 << n) - 1:
                return 0
            else:
                return -1

        best_res = -2
        for move in moves:
            res = -solve(mask_alice | (1 << move), mask_bob, 1)
            if res > best_res:
